-- L04-K1-series.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   the anime-mix group, 50 series groups, their series rows, 364 arcs, 998 characters and 704 openings and endings.
-- Needs:  L01, 011.
-- Verify: select count(*) from public.series where group_id in (select id from public.groups where site_id = 'anime');   expect 50
-- Undo:   L04-K1-series.rollback.sql (refused while a quiz or a reader row uses these groups).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if not exists (select 1 from public.sites where id = 'anime') or to_regclass('public.series') is null or to_regclass('public.arcs') is null or to_regclass('public.characters') is null or to_regclass('public.series_themes') is null then
    raise exception 'L04: apply L01 and 011 first';
  end if;
end $o1l$;

do $o1l$ begin
  if exists (select 1 from public.groups where slug in ('apothecary-diaries', 'attack-on-titan', 'black-clover', 'bleach', 'blue-lock', 'bocchi-the-rock', 'chainsaw-man', 'code-geass', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'detective-conan', 'dr-stone', 'dragon-ball', 'evangelion', 'fairy-tail', 'frieren', 'fruits-basket', 'fullmetal-alchemist', 'gintama', 'haikyu', 'hunter-x-hunter', 'inuyasha', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaguya-sama-love-is-war', 'kaiju-no-8', 'mob-psycho-100', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 're-zero', 'sailor-moon', 'sakamoto-days', 'slam-dunk', 'solo-leveling', 'spy-x-family', 'steins-gate', 'sword-art-online', 'that-time-i-got-reincarnated-as-a-slime', 'tokyo-ghoul', 'tokyo-revengers', 'tower-of-god', 'vinland-saga', 'violet-evergarden', 'anime-mix') and site_id <> 'anime') then
    raise exception 'L04: a series slug is already a group of another site';
  end if;
end $o1l$;


















































































































































































































































































































































































































































































